const text = $input.first().json.data;
const matches = [...text.matchAll(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g)];
return matches.map(m => ({
  json: {
    url: m[2],
    description: m[1],
    owner: 'mostafa@epam.com'
  }
}));

